#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    size_t len;
    unsigned char *d;
} Big;

static Big big_from_u(unsigned int v) {
    Big x = {0, NULL};
    if (v == 0) {
        x.len = 1;
        x.d = (unsigned char *)malloc(1);
        x.d[0] = 0;
        return x;
    }
    unsigned int t = v;
    while (t > 0) {
        t /= 10;
        x.len++;
    }
    x.d = (unsigned char *)malloc(x.len);
    t = v;
    for (size_t i = 0; i < x.len; ++i) {
        x.d[i] = (unsigned char)(t % 10);
        t /= 10;
    }
    return x;
}

static Big big_add(const Big *a, const Big *b) {
    size_t max = a->len > b->len ? a->len : b->len;
    unsigned char *d = (unsigned char *)calloc(max + 1, 1);
    unsigned int carry = 0;
    size_t i = 0;
    for (; i < max; ++i) {
        unsigned int av = i < a->len ? a->d[i] : 0;
        unsigned int bv = i < b->len ? b->d[i] : 0;
        unsigned int s = av + bv + carry;
        d[i] = (unsigned char)(s % 10);
        carry = s / 10;
    }
    if (carry) {
        d[i++] = (unsigned char)carry;
    }
    Big out = {i, d};
    return out;
}

static void big_free(Big *x) {
    free(x->d);
    x->d = NULL;
    x->len = 0;
}

static void big_print(const Big *x) {
    for (size_t i = x->len; i-- > 0;) {
        putchar((int)('0' + x->d[i]));
    }
    putchar(10);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s N", argv[0]);
        fputc(10, stderr);
        return 1;
    }

    errno = 0;
    char *end = NULL;
    unsigned long long n = strtoull(argv[1], &end, 10);
    if (argv[1][0] == '-' || !argv[1][0] || (end && *end != 0) || errno == ERANGE) {
        fputs("N must be a non-negative integer", stderr);
        fputc(10, stderr);
        return 1;
    }

    Big a = big_from_u(0);
    Big b = big_from_u(1);

    for (unsigned long long i = 0; i < n; ++i) {
        Big c = big_add(&a, &b);
        big_free(&a);
        a = b;
        b = c;
    }

    big_print(&a);
    big_free(&a);
    big_free(&b);
    return 0;
}
